grep 'FM-3.1' agents/tech-lead/ERROR_LOG.jsonl 2>/dev/null | python3 -c "
import sys, json
errors = []
for line in sys.stdin:
    try:
        d = json.loads(line.strip())
        errors.append(d)
    except: pass
# Classify
from collections import Counter
categories = Counter()
for e in errors:
    crit = e.get('critique', '') or e.get('error', '')
    if 'ENV_ASSUMPTION' in crit:
        categories['ENV_ASSUMPTION'] += 1
    elif 'NON_DELIVERY' in crit or 'Non-delivery' in crit:
        categories['NON_DELIVERY'] += 1
    elif 'TASK_ALREADY_DONE' in crit:
        categories['TASK_ALREADY_DONE_MISREAD'] += 1
    elif 'spec mismatch' in crit.lower():
        categories['SPEC_MISMATCH'] += 1
    else:
        categories['OTHER'] += 1
print('=== FM-3.1 Breakdown ===')
for k,v in categories.most_common():
    print(f'  {k}: {v}')
print(f'Total: {len(errors)}')
print()
for e in errors:
    print(f'  [{e.get(\"context\",\"?\")}] {e.get(\"error\",\"\")} — {e.get(\"critique\",\"\")[:120]}')
" 2>&1

